export const getRandomWord = (mode = 'Normal') => {
    if (mode === 'Easy') return easyWords[Math.floor(Math.random() * easyWords.length)];
    if (mode === 'Wet') return 'wet';
    if (mode === 'Normal') return normalWords[Math.floor(Math.random() * normalWords.length)];
    if (mode === 'Hard') return hardWords[Math.floor(Math.random() * hardWords.length)];
    if (mode === 'Super Hard') return superHardWords[Math.floor(Math.random() * superHardWords.length)];
    if (mode === 'Insane') return insaneWords[Math.floor(Math.random() * insaneWords.length)];
    if (mode === 'Crazy') return crazyWords[Math.floor(Math.random() * crazyWords.length)];
    if (mode === 'Master') return longWords[Math.floor(Math.random() * longWords.length)];
    if (mode === 'Impossible') return impossibleWords[Math.floor(Math.random() * impossibleWords.length)];
    return normalWords[Math.floor(Math.random() * normalWords.length)];
};
